package main
import("context";"errors";"flag";"log";"net";"net/http";"os";"os/signal";"syscall";"time";"github.com/Ploos-AS/BotWeb/internal/server")
func main(){listen:=flag.String("listen","127.0.0.1:8080","HTTP listen address");registry:=flag.String("registry","bots.json","bot registry JSON");flag.Parse();auth:=server.AuthConfig{ViewerToken:os.Getenv("BOTWEB_VIEWER_TOKEN"),OperatorToken:os.Getenv("BOTWEB_OPERATOR_TOKEN"),TrustProxy:os.Getenv("BOTWEB_TRUST_PROXY")=="1"};s,err:=server.NewWithAuth(*registry,auth);if err!=nil{log.Fatal(err)};if !authEnabled(auth)&&!isLoopbackListen(*listen){log.Fatal("refusing non-loopback listen without BOTWEB_VIEWER_TOKEN or BOTWEB_OPERATOR_TOKEN")};srv:=newHTTPServer(*listen,s.Handler());stop:=make(chan os.Signal,1);signal.Notify(stop,os.Interrupt,syscall.SIGTERM);go func(){<-stop;ctx,cancel:=context.WithTimeout(context.Background(),10*time.Second);defer cancel();if err:=srv.Shutdown(ctx);err!=nil{log.Printf("HTTP shutdown: %v",err)}}();log.Printf("BotWeb listening on %s",*listen);if err:=srv.ListenAndServe();err!=nil&&!errors.Is(err,http.ErrServerClosed){log.Fatal(err)}}
func authEnabled(a server.AuthConfig)bool{return a.ViewerToken!=""||a.OperatorToken!=""}
func isLoopbackListen(addr string)bool{host,_,err:=net.SplitHostPort(addr);if err!=nil{return false};ip:=net.ParseIP(host);return host=="localhost"||(ip!=nil&&ip.IsLoopback())}

func newHTTPServer(addr string,h http.Handler)*http.Server{return &http.Server{Addr:addr,Handler:h,ReadHeaderTimeout:5*time.Second,ReadTimeout:15*time.Second,WriteTimeout:30*time.Second,IdleTimeout:60*time.Second}}
